(1, 'admin', 'admin');
INSERT INTO `diseases` (`id`, `disease_name`, `symptoms`, `precautions`, `prevention_methods`, `medication`) VALUES
(1, 'ملیریا', 'بخار ، الٹی ، سر درد ، پیلے رنگ کی جلد [1]', 'مچھر کے جال ، کیڑے مکوڑے ، مچھر پر قابو پانے ، دوائیں [1]', 'ملیریا کو روکنے کے لئے استعمال ہونے والے طریقوں میں دوائیں ، مچھر کا خاتمہ اور کاٹنے کی روک تھام شامل ہیں۔2023 تک ، ملیریا کے دو ویکسین موجود ہیں ، جو بچوں میں استعمال کے لئے منظور شدہ ہیں: آر ٹی ایس ، ایس اور آر 21۔ [14] [71]کسی علاقے میں ملیریا کی موجودگی کے لئے اعلی انسانی آبادی کی کثافت ، اعلی انوفیلس مچھروں کی آبادی کی کثافت اور انسانوں سے مچھروں اور مچھروں سے انسانوں میں ٹرانسمیشن کی اعلی شرحوں کے امتزاج کی ضرورت ہوتی ہے۔اگر ان میں سے کسی کو کافی حد تک کم کیا گیا ہے تو ، بالآخر اس علاقے سے پرجیوی غائب ہوجاتا ہے ، جیسا کہ شمالی امریکہ ، یورپ اور مشرق وسطی کے کچھ حصوں میں ہوا ہے۔تاہم ، جب تک کہ پرجیوی کو پوری دنیا سے ختم نہیں کیا جاتا ہے ، اگر یہ حالات کسی ایسے امتزاج کی طرف لوٹ آئیں جو پرجیوی کے پنروتپادن کے حامی ہیں۔مزید برآں ، انوفیلس مچھروں کو ختم کرنے پر فی شخص لاگت آبادی کی کثافت میں کمی کے ساتھ بڑھتی ہے ، جس سے کچھ علاقوں میں معاشی طور پر ناقابل برداشت ہوجاتا ہے۔ [] २]', ' دوا'),
(2, 'تپ دق', 'دائمی کھانسی ، بخار ، خونی بلغم کے ساتھ کھانسی ، وزن میں کمی [1]', 'ان لوگوں کی اسکریننگ کرنا جو زیادہ خطرہ میں ہیں ، متاثرہ افراد کا علاج ، بیسیلس کالیٹ گورین (بی سی جی) کے ساتھ ویکسینیشن [3] [4] [5]', 'تپ دق کی روک تھام اور کنٹرول کی کوششیں بنیادی طور پر نوزائیدہ بچوں کی ویکسینیشن اور فعال معاملات کا پتہ لگانے اور مناسب علاج پر انحصار کرتی ہیں۔ [15]ورلڈ ہیلتھ آرگنائزیشن (ڈبلیو ایچ او) نے علاج معالجے کی بہتر حکمرانی کے ساتھ کچھ کامیابی حاصل کی ہے ، اور کیس کی تعداد میں تھوڑی کمی واقع ہوئی ہے۔ [15]کچھ ممالک کے پاس غیر ارادی طور پر نظربند کرنے یا ان کی جانچ پڑتال کے لئے قانون سازی ہوتی ہے جو ان لوگوں کو تپ دق ہونے کا شبہ کرتے ہیں ، یا اگر انفکشن ہو تو غیر ارادی طور پر ان کا علاج کریں۔ [113]', 'antimalarial دوا نہیں ملی۔'),
(3, 'ملیریا', 'بخار ، الٹی ، سر درد ، پیلے رنگ کی جلد [1]', 'مچھر کے جال ، کیڑے مکوڑے ، مچھر پر قابو پانے ، دوائیں [1]', 'ملیریا کو روکنے کے لئے استعمال ہونے والے طریقوں میں دوائیں ، مچھر کا خاتمہ اور کاٹنے کی روک تھام شامل ہیں۔2023 تک ، ملیریا کے دو ویکسین موجود ہیں ، جو بچوں میں استعمال کے لئے منظور شدہ ہیں: آر ٹی ایس ، ایس اور آر 21۔ [14] [71]کسی علاقے میں ملیریا کی موجودگی کے لئے اعلی انسانی آبادی کی کثافت ، اعلی انوفیلس مچھروں کی آبادی کی کثافت اور انسانوں سے مچھروں اور مچھروں سے انسانوں میں ٹرانسمیشن کی اعلی شرحوں کے امتزاج کی ضرورت ہوتی ہے۔اگر ان میں سے کسی کو کافی حد تک کم کیا گیا ہے تو ، بالآخر اس علاقے سے پرجیوی غائب ہوجاتا ہے ، جیسا کہ شمالی امریکہ ، یورپ اور مشرق وسطی کے کچھ حصوں میں ہوا ہے۔تاہم ، جب تک کہ پرجیوی کو پوری دنیا سے ختم نہیں کیا جاتا ہے ، اگر یہ حالات کسی ایسے امتزاج کی طرف لوٹ آئیں جو پرجیوی کے پنروتپادن کے حامی ہیں۔مزید برآں ، انوفیلس مچھروں کو ختم کرنے پر فی شخص لاگت آبادی کی کثافت میں کمی کے ساتھ بڑھتی ہے ، جس سے کچھ علاقوں میں معاشی طور پر ناقابل برداشت ہوجاتا ہے۔ [] २]', 'antimalarial دوا'),
(4, 'دمہ', 'گھرگھراہٹ ، کھانسی ، سینے کی تنگی ، سانس کی قلت کی بار بار چلنے والی اقساط [4]', 'احتیاطی تدابیر نہیں ملی۔', 'دمہ کی ترقی کو روکنے کے لئے اقدامات کی تاثیر کے ثبوت کمزور ہیں۔ [146]ورلڈ ہیلتھ آرگنائزیشن نے تمباکو کے تمباکو نوشی ، فضائی آلودگی ، خوشبو سمیت کیمیائی خارش ، اور سانس کے انفیکشن کی تعداد جیسے خطرے والے عوامل کو کم کرنے کی سفارش کی ہے۔ [147] [147] [148]دوسری کوششوں میں جو وعدہ کرتے ہیں ان میں شامل ہیں: یوٹرو میں دھواں کی نمائش کو محدود کرنا ، دودھ پلانے ، اور ڈے کیئر یا بڑے خاندانوں کی نمائش میں اضافہ ، لیکن اس اشارے کے لئے سفارش کرنے کے لئے کسی کو بھی اتنی مدد نہیں دی جاتی ہے۔ [146]', 'antimalarial دوا نہیں ملی۔'),
(5, 'ہائی بلڈ پریشر', 'کوئی نہیں [1]', 'احتیاطی تدابیر نہیں ملی۔', 'ہائی بلڈ پریشر کے زیادہ تر بیماریوں کا بوجھ ان لوگوں کے ذریعہ ہوتا ہے جنھیں ہائپرٹینسیس کا لیبل نہیں لگایا جاتا ہے۔ [] 99]اس کے نتیجے میں ، آبادی کی حکمت عملیوں کو ہائی بلڈ پریشر کے نتائج کو کم کرنے اور اینٹی ہائپرپروسینٹ دوائیوں کی ضرورت کو کم کرنے کی ضرورت ہے۔دواؤں کو شروع کرنے سے پہلے ، بلڈ پریشر کو کم کرنے کے لئے طرز زندگی میں ہونے والی تبدیلیوں کی سفارش کی جاتی ہے۔2004 کے برٹش ہائی بلڈ پریشر سوسائٹی کے رہنما خطوط [100] نے ہائی بلڈ پریشر کی بنیادی روک تھام کے لئے 2002 میں امریکی نیشنل ہائی بی پی ایجوکیشن پروگرام [101] کے ذریعہ بیان کردہ طرز زندگی میں تبدیلی کی تجویز پیش کی تھی۔', 'antimalarial دوا نہیں ملی۔'),
(6, 'نشانات و علامات', 'cell- سیل فنکشن کے جینیاتی نقائص\nنوجوانوں کی پختگی شروع ہونے والی ذیابیطس\nمائٹوکونڈریل ڈی این اے اتپریورتن\nانسولین پروسیسنگ یا انسولین ایکشن میں جینیاتی نقائص\nپروئنسولن کے تبادلوں میں نقائص\nانسولین جین تغیرات\nانسولین رسیپٹر اتپریورتن\nایکوکرائن لبلبے کی نقائص (قسم 3C ذیابیطس دیکھیں ، یعنی پینکریٹوجینک ذیابیطس)\nدائمی لبلبے کی سوزش\nپینکریٹیکٹومی\nلبلبے کی نوپلاسیا\nانبانی کیفیت\nہیموچروومیٹوسس\nفائبروکلکلیسل لبلبے کی پوٹھی', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(7, 'نشانات و علامات', 'بالغوں کے ل body جسمانی وزن کو معمول کے مطابق برقرار رکھیں (جیسے باڈی ماس انڈیکس 20-25 کلوگرام/ایم 2)\nغذائی سوڈیم کی مقدار کو <100 ملی میٹر/دن (<6 جی سوڈیم کلورائد یا <2.4 جی سوڈیم فی دن) میں کم کریں)\nباقاعدگی سے ایروبک جسمانی سرگرمی میں مشغول ہوں جیسے تیز چلنا (روزانہ 30 منٹ ، ہفتے کے بیشتر دن)\nشراب کے استعمال کو مردوں میں 3 یونٹ/دن سے زیادہ اور خواتین میں 2 یونٹ/دن سے زیادہ تک محدود رکھیں\nپھلوں اور سبزیوں سے بھرپور غذا کھائیں (جیسے روزانہ کم از کم پانچ حصے)\nتناؤ میں کمی [102]', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(8, 'نشانات و علامات', 'مختصر اداکاری کرنے والا بیٹا 2-ایڈرینوسیپٹر ایگونسٹس (ایس اے بی اے) ، جیسے سالبوٹامول (البٹیرول یو ایس اے این) دمہ کی علامات کے لئے پہلی لائن ٹریٹمنٹ ہیں۔ [8]ورزش سے متاثرہ علامات والے افراد میں ورزش سے پہلے ان کی سفارش کی جاتی ہے۔ [188]\nاعتدال پسند یا شدید علامات والے افراد میں ایس اے بی اے کے ساتھ مل کر استعمال ہونے پر اینٹیکولینرجک ادویات ، جیسے آئپراٹروپیم ، اضافی فائدہ فراہم کرتے ہیں اور اسپتالوں میں داخل ہونے سے بچ سکتے ہیں۔ [8] [189] [190]اگر کوئی شخص صبا کو برداشت نہیں کرسکتا ہے تو اینٹیکولینرجک برونکوڈیلیٹرز بھی استعمال ہوسکتے ہیں۔ [105]اگر کسی بچے کو اسپتال میں داخلے کی ضرورت ہوتی ہے تو اضافی Ipratropium کسی صبا سے زیادہ مدد کرنے کے لئے ظاہر نہیں ہوتا ہے۔ [191]شدید دمہ کی علامات کے حامل 2 سال سے زیادہ عمر کے بچوں کے لئے ، سانس لینے والی اینٹیکولینجک ادویات تنہا لی جاتی ہیں لیکن اتنی موثر نہیں ہوتی ہیں جتنی سانس والے صبا یا صبا anted کے ساتھ مل کر سانس لیا جاتا ہے۔ [192] [189]بالغ افراد جو مشترکہ سانس لینے والی دوائیں وصول کرتے ہیں جن میں مختصر اداکاری کرنے والے اینٹیکولینرجکس اور ایس اے بی اے شامل ہیں ، ان لوگوں کے مقابلے میں صبا کے ساتھ سلوک کرنے والے لوگوں کے مقابلے میں زلزلے ، اشتعال انگیزی اور دل کی دھڑکنوں کا سامنا کرنے جیسے منفی اثرات کے بڑھتے ہوئے اثرات کا خطرہ ہوسکتا ہے۔ [190]\nپرانے ، کم منتخب ایڈرینجک ایگونسٹس ، جیسے سانس لینے والے ایپیینفرین ، سباس سے اسی طرح کی افادیت رکھتے ہیں۔ [193]تاہم ضرورت سے زیادہ کارڈیک محرک سے متعلق خدشات کی وجہ سے ان کی سفارش نہیں کی جاتی ہے۔ [194]\nکورٹیکوسٹیرائڈز ان کی اینٹی انفلامیٹری خصوصیات کی وجہ سے بڑھتے ہوئے شدید مرحلے میں بھی مدد کرسکتے ہیں۔سیسٹیمیٹک اور زبانی کورٹیکوسٹیرائڈز کا فائدہ اچھی طرح سے قائم ہے۔سانس یا نیبولائزڈ کورٹیکوسٹیرائڈز بھی استعمال ہوسکتے ہیں۔ [152]شدید دمہ کی وجہ سے اسپتال میں موجود بڑوں اور بچوں کے لئے ، سیسٹیمیٹک (IV) کورٹیکوسٹیرائڈز علامات کو بہتر بناتے ہیں۔ [195] [196]شدید دمہ کی خرابی کے بعد کورٹیکوسٹیرائڈز کا ایک مختصر کورس سے دوبارہ ہونے سے بچنے اور اسپتال میں داخل ہونے کو کم کرنے میں مدد مل سکتی ہے۔ [197]\nدوسرے علاج ، کم قائم ، نس ناستی یا نیبولائزڈ میگنیشیم سلفیٹ اور آکسیجن کے ساتھ ملائے گئے ہیلیم ہیں۔امینوفیلین کو بھی احتیاط کے ساتھ استعمال کیا جاسکتا ہے۔ [152]\nمکینیکل وینٹیلیشن شدید ہائپوکسیمیا کی صورت میں آخری حربہ ہے۔ [152]\nجب منشیات کے امینوفیلین کی نس ناستی انتظامیہ برونکوڈیلیشن میں بہتری فراہم نہیں کرتی ہے جب معیاری سانس لینے والے بیٹا -2 ایگونسٹ علاج کے مقابلے میں۔ [198]امینوفیلین علاج سانس لینے والے بیٹا -2 ایگونسٹ علاج کے مقابلے میں زیادہ منفی اثرات کے ساتھ وابستہ ہے۔ [198]', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(9, 'یتیمولوجی اور تعریفیں', 'انسانی پیپیلوما وائرس (گریوا کینسر) ،\nایپسٹین-بار وائرس (بی سیل لیمفروپولیفریٹو بیماری اور ناسوفرینگل کارسنوما) ،\nکاپوسی کا سرکوما ہرپس وائرس (کاپوسی کا سارکوما اور پرائمری فیوژن لیمفوماس) ،\nہیپاٹائٹس بی اور ہیپاٹائٹس سی وائرس (ہیپاٹوسیلولر کارسنوما)\nہیومن ٹی سیل لیوکیمیا وائرس 1 (ٹی سیل لیوکیمیاس)۔\nمرکل سیل پولیوما وائرس (مرکل سیل کارسنوما)', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'اسکریننگ ٹیسٹ سے ممکنہ نقصانات: مثال کے طور پر ، ایکس رے کی تصاویر میں ممکنہ طور پر نقصان دہ آئنائزنگ تابکاری کی نمائش شامل ہے\nٹیسٹ کے امکانات کینسر کی صحیح شناخت کرتے ہیں\nکینسر موجود ہونے کا امکان: نایاب کینسر کے لئے اسکریننگ عام طور پر مفید نہیں ہے۔\nفال'),
(10, 'نشانات و علامات', 'الزائمر اے (1907)۔\"über Eine Eigenartige Erkrankung der Hirnrinde\" [دماغی پرانتستا کی ایک عجیب بیماری کے بارے میں]۔allgemeine Zeitschrift für نفسیاتی and sychiscisch-gerichtlich میڈیزین (جرمن زبان میں)۔64 (1–2): 146–148۔\n\"دماغی پرانتستا کی ایک عجیب و غریب بیماری کے بارے میں۔ الوئس الزائمر ، 1907 (ایل جاروک اور ایچ گرینسن نے ترجمہ کیا)\"۔الزائمر بیماری اور اس سے وابستہ عوارض۔1 (1)H. Greenson کے ذریعہ ترجمہ: 3–8۔1987. پی ایم آئی ڈی 3331112۔\nمورر یو ، مورر کے (2003)۔الزائمر: ایک معالج کی زندگی اور ایک بیماری کا کیریئر۔نیو یارک: کولمبیا یونیورسٹی پریس۔پی270. ISBN 978-0-231-11896-5.', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'الزائمر اے (1907)۔\"über Eine Eigenartige Erkrankung der Hirnrinde\" [دماغی پرانتستا کی ایک عجیب بیماری کے بارے میں]۔allgemeine Zeitschrift für نفسیاتی and sychiscisch-gerichtlich میڈیزین (جرمن زبان میں)۔64 (1–2): 146–148۔\n\"دماغی پرانتستا کی ایک عجیب و غریب'),
(11, 'درجہ بندی', 'کورٹیکوباسل سنڈروم۔\nلیوی لاشوں کے ساتھ ڈیمینشیا - لیوڈوڈوپا مزاحمت ، موٹر علامات سے پہلے علمی غلبہ ، اور اتار چڑھاؤ سے علمی علامات ، (اس بیماری میں بصری فریب کاری عام ہے)\nضروری زلزلے - یہ پہلے تو پارکنسنزم کی طرح نظر آسکتا ہے ، لیکن اس میں کلیدی فرق ہے۔ضروری زلزلے میں ، زلزلہ عمل کے ساتھ بدتر ہوجاتا ہے (PD میں بہتری لاتا ہے) ، PD میں دیگر علامات کی کمی عام ہے ، اور عام ڈیٹاسکن دیکھا جاتا ہے۔ [106]\nایک سے زیادہ سسٹم ایٹروفی - لیوڈوڈوپا مزاحمت ، تیزی سے ترقی پسند ، خودمختاری کی ناکامی ، اسٹریڈور ، موجودہ بابنسکی سائن ، سیریبلر ایٹیکسیا ، اور ایم آر آئی کے مخصوص نتائج\nپروگریسو سوپرانیوکلیئر فالج - لیوڈوڈوپا مزاحمت ، پابندی والی عمودی نگاہیں ، مخصوص ایم آر آئی کے نتائج ، اور ابتدائی اور مختلف پوسٹورل مشکلات', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(12, 'نشانات و علامات', 'پرائمری ایچ آئی وی انفیکشن: یا تو asymptomatic ہوسکتا ہے یا شدید ریٹرو وائرل سنڈروم سے وابستہ ہوسکتا ہے [31]\nمرحلہ I: ایچ آئی وی انفیکشن ایک سی ڈی 4+ ٹی سیل گنتی (جسے سی ڈی 4 گنتی کے نام سے بھی جانا جاتا ہے) کے ساتھ خون کے 500 سے زیادہ فی مائکولیٹری (µl یا کیوبک ملی میٹر) سے زیادہ کے ساتھ غیر متزلزل ہے۔ [31]عام طور پر لمف نوڈ توسیع شامل ہوسکتی ہے۔ [31]\nمرحلہ دوم: ہلکے علامات ، جس میں معمولی mucocutaneous توضیحات اور بار بار ہونے والی اوپری سانس کی نالی کے انفیکشن شامل ہوسکتے ہیں۔500/µL سے کم کی ایک CD4 گنتی [31]\nمرحلہ III: اعلی درجے کی علامات ، جس میں ایک مہینے سے زیادہ عرصے تک غیر واضح دائمی اسہال ، پھیپھڑوں کے تپ دق سمیت شدید بیکٹیریل انفیکشن ، اور 350/µL سے کم سی ڈی 4 کی گنتی شامل ہوسکتی ہے [31]\nاسٹیج چہارم یا ایڈز: شدید علامات ، جس میں دماغ کا ٹاکسوپلاسموسس ، غذائی نالی کے کینڈیڈیسیس ، ٹریچیا ، برونچی ، یا پھیپھڑوں ، اور کپوسی کا سارکوما شامل ہے۔200/µl سے کم کی ایک CD4 گنتی [31]', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(13, 'نشانات و علامات', 'انفلوئنزا اے وائرس (IAV) ، جینس الفینفلوینزا وائرس\nانفلوئنزا بی وائرس (IBV) ، جینس Betainfluenzavirus\nانفلوئنزا سی وائرس (آئی سی وی) ، جینس جیمینفلوینزا وائرس\nانفلوئنزا ڈی وائرس (IDV) ، جینس ڈیلٹن فلوینزا وائرس', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(14, 'تاریخ', '2016 میں ہر 100،000 افراد میں تپ دق کے نئے معاملات کی تعداد [188]\n\n\n\n2012 میں تپ دق کی اموات فی ملین افراد\n\n\n\nخطے کے لحاظ سے تپ دق کی اموات ، 1990 سے 2017 [189]', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(15, 'نشانات و علامات', 'شعور کم ہوا\nاہم کمزوری اس طرح کہ وہ شخص چلنے سے قاصر ہے\nکھانا کھلانے میں ناکامی\nدو یا زیادہ آکشیپ\nکم بلڈ پریشر (بالغوں میں 70 ملی میٹر ایچ جی سے کم اور بچوں میں 50 ملی میٹر ایچ جی)\nسانس لینے کے مسائل\nگردش کا جھٹکا\nپیشاب میں گردے کی ناکامی یا ہیموگلوبن\nخون بہہ رہا ہے ، یا ہیموگلوبن 50 جی/ایل (5 جی/ڈی ایل) سے کم\nپلمونری ورم میں کمی لاتے\nبلڈ گلوکوز 2.2 ملی میٹر/ایل (40 ملی گرام/ڈی ایل) سے کم\nتیزابیت یا لییکٹیٹ کی سطح 5 ملی میٹر/ایل سے زیادہ ہے\nکم شدت سے ٹرانسمیشن علاقوں میں 100،000 سے زیادہ فی مائکولیٹریٹری (μl) کے خون میں ایک پرجیوی سطح ، یا اعلی شدت سے ٹرانسمیشن علاقوں میں 250،000 فی μl', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(16, 'نشانات و علامات', 'آب و ہوا کی تبدیلی اور متعدی امراض#ڈینگی بخار\nڈینگی بخار کے پھیلنے', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(17, 'تاریخ اور نام', 'کسی ایسے ملک میں رہا ہے جس میں بڑے پیمانے پر ایبولا بیماری کی منتقلی ہو اور نہ ہی کوئی معروف نمائش (کم خطرہ) ہو۔یا 21 دن سے زیادہ پہلے اس ملک میں رہا ہے (کوئی خطرہ نہیں)\nعلامات ظاہر کرنے والے شخص سے مقابلہ ؛لیکن پی پی ای پہنے بغیر ایبولا والے شخص کے تین فٹ کے اندر نہیں۔اور جسمانی سیالوں سے براہ راست رابطہ نہیں ہے\nایبولا کی بیماری کی علامات ظاہر کرنے والے کسی شخص سے جلد کا مختصر رابطہ ہونے کے بعد جب اس شخص کے بارے میں خیال کیا جاتا تھا کہ وہ زیادہ متعدی نہیں ہے (کم خطرہ)\nایبولا کی وسیع پیمانے پر بیماری کے بغیر ان ممالک میں: پی پی ای (کم خطرہ) پہنے ہوئے اس بیماری کی علامات ظاہر کرنے والے شخص سے براہ راست رابطہ (کم خطرہ)\nاس شخص سے پہلے کسی شخص کے ساتھ رابطہ کریں جس سے پہلے کہ وہ شخص علامات ظاہر کر رہا ہو (کوئی خطرہ نہیں)۔', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(18, 'نشانات و علامات', 'نس بندی: ان تمام مادوں کا مناسب تصرف اور علاج جو شاید ہیضے کے شکار دوسرے لوگوں کے ملانے (جیسے لباس ، بستر ، وغیرہ) کے ساتھ رابطے میں آئے ہوں۔اگر ممکن ہو تو کلورین بلیچ کا استعمال کرتے ہوئے ، گرم پانی میں دھونے سے ان کو صاف کیا جانا چاہئے۔وہ ہاتھ جو ہیضے کے مریضوں کو چھوتے ہیں یا ان کے لباس ، بستر وغیرہ کو ، کلورینڈ پانی یا دیگر موثر antimicrobial ایجنٹوں سے اچھی طرح صاف اور جراثیم کشی کرنی چاہئے۔\nسیوریج اور فیکل کیچڑ کا انتظام: ہیضے سے متاثرہ علاقوں میں ، گند نکاسی اور فیکل کیچڑ کو انسانی اخراج کے ذریعہ اس بیماری کے پھیلاؤ کو روکنے کے لئے احتیاط سے علاج اور انتظام کرنے کی ضرورت ہے۔صفائی ستھرائی اور حفظان صحت کی فراہمی ایک اہم روک تھام اقدام ہے۔ [35]کھلی شوچ ، غیر علاج شدہ سیوریج کی رہائی ، یا ماحول میں گڑھے لیٹرینز یا سیپٹک ٹینکوں سے فیکل کیچڑ کو پھینکنے کو روکنے کی ضرورت ہے۔ [] 46]بہت سے ہیضے سے متاثرہ زون میں ، سیوریج کا علاج کم ڈگری ہے۔ [] 47] [48]لہذا ، خشک بیت الخلاء کا نفاذ جو پانی کی آلودگی میں معاون نہیں ہے ، کیونکہ وہ پانی سے فلش نہیں ہوتے ہیں ، فلش بیت الخلاء کا ایک دلچسپ متبادل ہوسکتا ہے۔ [] 49]\nذرائع: ممکنہ استعمال کے لئے پانی (ابلتے ، کلورینیشن وغیرہ) کو کس طرح ختم کرنے کا طریقہ کے ساتھ آلودہ پانی کے ذرائع کے گرد ممکنہ طور پر ہیضے کی آلودگی کے بارے میں انتباہات پوسٹ کی جانی چاہئیں۔\nپانی کی تزکیہ: شراب پینے ، دھونے یا کھانا پکانے کے لئے استعمال ہونے والے تمام پانی کو یا تو ابلتے ، کلورینیشن ، اوزون واٹر ٹریٹمنٹ ، الٹرا وایلیٹ لائٹ نسبندی (جیسے شمسی پانی کی ڈس انفیکشن کے ذریعہ) ، یا کسی بھی علاقے میں اینٹی مائکروبیل فلٹریشن کے ذریعہ جراثیم سے پاک کیا جانا چاہئے جہاں چولیرا موجود ہوسکتا ہے۔کلورینیشن اور ابلتے عام طور پر ٹرانسمیشن کو روکنے کے کم سے کم مہنگے اور سب سے موثر ذریعہ ہوتے ہیں۔بنگلہ دیش کے غریب دیہات میں استعمال ہونے پر کپڑوں کے فلٹرز یا ساڑھی فلٹریشن ، اگرچہ بہت بنیادی ہے ، نے ہیضے کی موجودگی کو نمایاں طور پر کم کردیا ہے۔بہتر اینٹی مائکروبیل فلٹرز ، جیسے جدید انفرادی پانی کے علاج میں پیدل سفر کٹس میں موجود ہیں ، سب سے زیادہ موثر ہیں۔صحت عامہ کی تعلیم اور صفائی ستھرائی کے مناسب طریقوں پر عمل پیرا ہونا ہیضہ اور دیگر بیماریوں کی منتقلی اور کنٹرول میں مدد کے لئے بنیادی اہمیت کا حامل ہے۔', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(19, 'نشانات و علامات', 'میڈیسن پورٹل وائرس پورٹل', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(20, 'نشانات و علامات', 'ایچ سی وی جینی ٹائپ 1 اے (کوئی سروسس نہیں): 8 ہفتوں کے گلیکاپریویر/پیبرینٹاسویر یا لیڈپاسویر/سوفوسوبویر (ان لوگوں کے لئے جو ایچ آئی وی/ایڈز نہیں رکھتے ہیں ، وہ افریقی نژاد امریکی نہیں ہیں ، اور ان میں خون کی 6 ملین سے کم ایچ سی وی وائرل کاپیاں ہیں۔) یا ایلباسویر/گرازوپرویر کے 12 ہفتوں ، لیڈپاسویر/صوفوسبوویر ، یا صوفوسبوویر/ویلپاتاسویر۔ [88]ڈیکلاتسویر یا سیمپریویر کے ساتھ صوفوسبوویر بھی استعمال کیا جاسکتا ہے۔ [] 86]\nHCV جینیٹائپ 1A (معاوضہ سرہوسیس کے ساتھ): گلیکاپریویر/پیبرینٹاسویر کے 8 ہفتوں یا ایلباسویر/گرازوپرویر کے 12 ہفتوں ، لیڈپاسویر/سوفوسبوویر ، یا سوفوسبوویر/ویلپاتاسویر۔وزن پر مبنی رباویرین کے ساتھ ایلباسویر/گریزوپرویر کا ایک متبادل علاج 16 ہفتوں تک استعمال کیا جاسکتا ہے اگر ایچ سی وی کو این ایس 5 اے پروٹیز انبیبیٹرز کے خلاف اینٹی ویرل مزاحمت کی تغیرات پایا جاتا ہے۔ [89]\nایچ سی وی جینیوٹائپ 1 بی (کوئی سروسس نہیں): 8 ہفتوں کے گلیکاپریویر/پبرینٹاسویر یا لیڈپاسویر/صوفوسوبویر (مذکورہ بالا کے لئے مذکورہ بالا حدود کے ساتھ) یا ایلباسویر/گریزوویر/سوفوسوبیر ، یا سوفوسوبیر ، یا 12 ہفتوں کے ساتھ۔متبادل رجیموں میں 12 ہفتوں کے اومبیٹاسویر/پیریٹاپریویر/رتونویر کے ساتھ داسابویر یا 12 ہفتوں میں صوفوسبوویر کے ساتھ ڈیکلاتسویر یا سائمپیروئیر شامل ہیں۔ [90]\nHCV جینیٹائپ 1 بی (معاوضہ سرہوسیس کے ساتھ): 8 ہفتوں کے گلیکاپریویر/پیبرینٹاسویر یا ایلباسویر/گرازوپرویر کے 12 ہفتوں ، لیڈپاسویر/صوفوسبوویر ، یا سوفوسبوویر/ویلپاتاسویر۔پیریٹاپریویر/ریتونویر/اومبیٹاسویر کے ساتھ 12 ہفتوں کا کورس بھی استعمال کیا جاسکتا ہے۔ [91]\nایچ سی وی جین ٹائپ 2 (کوئی سروسس نہیں): 8 ہفتوں میں گلیکاپریویر/پیبرینٹاسویر یا 12 ہفتوں میں صوفوسبوویر/ویلپاتاسویر۔متبادل کے طور پر ، 12 ہفتوں کے صوفوسبوویر/ڈیکلاتسویر کو استعمال کیا جاسکتا ہے۔ [92]\nایچ سی وی جینو ٹائپ 2 (معاوضہ سرہوسیس کے ساتھ): گلیکپرویر/پیبرینٹاسویر کے 8 ہفتوں یا سوفوسبوویر/ویلپاتاسویر کے 12 ہفتوں۔صوفوسبوویر/ڈیکلاتسویر کی ایک متبادل طرز عمل 16-24 ہفتوں تک استعمال کی جاسکتی ہے۔ [] 93]\nایچ سی وی جینی ٹائپ 3 (کوئی سروسس نہیں): 8 ہفتوں کے گلیکاپریویر/پیبرینٹاسویر یا 12 ہفتوں کے سوفوسبوویر/ویلپاتاسویر یا سوفوسبوویر اور ڈیکلاتاسویر۔ [94]\nایچ سی وی جینیوٹائپ 3 (معاوضہ سرہوسیس کے ساتھ): گلیکاپریویر/پیبرینٹاسویر کے 8 ہفتوں یا 12 ہفتوں میں صوفوسبوویر/ویلپاتسویر کے 12 ہفتوں ، یا اگر کچھ اینٹی ویرل اتپریورتن موجود ہیں تو ، 12 ہفتوں میں صوفوسبویر/ویلپٹاسویر/ووکسلاپریویر (جب یقینی طور پر اینٹی وائرل/ووکلاپریویر) ہیں۔سوفوسبوویر اور ڈیکلاتسویر کے ہفتوں۔ [95]\nایچ سی وی جینیٹائپ 4 (کوئی سروسس نہیں): 8 ہفتوں میں گلیکاپریویر/پیبرینٹاسویر یا 12 ہفتوں کے سوفوسبوویر/ویلپاتاسویر ، ایلباسویر/گرازوپرویر ، یا لیڈپاسویر/صوفوسبویر۔اومبیٹاسویر/پیریٹاپریویر/ریتونویر کی 12 ہفتوں کا طریقہ بھی وزن پر مبنی رباویرن کے ساتھ مل کر قابل قبول ہے۔ [] 96]\nایچ سی وی جینی ٹائپ 4 (معاوضہ سرہوسیس کے ساتھ): 8 ہفتوں میں گلیکاپریویر/پیبرینٹاسویر یا 12 ہفتوں کے سوفوسبوویر/ویلپاتاسویر ، ایلباسویر/گرازوپرویر ، یا لیڈپاسویر/صوفوسبوویر کی سفارش کی جاتی ہے۔وزن پر مبنی رباویرن کے ساتھ اومبٹاسویر/پیریٹاپریویر/ریتونویر کا 12 ہفتوں کا کورس ایک قابل قبول متبادل ہے۔ [] 97]\nایچ سی وی جین ٹائپ 5 یا 6 (معاوضہ سرہوسیس کے ساتھ یا اس کے بغیر): 8 ہفتوں میں گلیکاپریویر/پبرینٹاسویر کی سفارش کی جاتی ہے۔اگر سروسس موجود ہے ، تو پھر سوفوسبوویر/ویلپاتسویر ، یا لیڈپاسویر/صوفوسبوویر کا 12 ہفتوں کا کورس ایک متبادل آپشن ہے۔ [] 98]', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(21, 'نشانات و علامات', 'کرلی میں شیزوفرینیا', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'کرلی میں شیزوفرینیا'),
(22, 'نشانات و علامات', 'بائپولر I ڈس آرڈر: تشخیص کرنے کے لئے کم از کم ایک انمول واقعہ ضروری ہے۔ [109] دوئبرووی خرابی کی شکایت I کے ساتھ زیادہ تر معاملات میں افسردہ اقساط عام ہیں ، لیکن تشخیص کے لئے غیر ضروری ہیں۔ [27]\"ہلکے ، اعتدال پسند ، اعتدال پسند ، شدید ، شدید\" اور \"نفسیاتی خصوصیات کے ساتھ\" جیسے مخصوص افراد کو شامل کیا جانا چاہئے تاکہ اس عارضے کی پیش کش اور اس کی نشاندہی کرنے کے لئے قابل اطلاق ہو۔ [5]\nبائپولر II کی خرابی کی شکایت: کوئی انمک اقساط اور ایک یا زیادہ ہائپوومینک اقساط اور ایک یا زیادہ بڑے افسردہ اقساط۔ [109]ہائپوومینک اقساط انماد کی پوری حد تک نہیں جاتے ہیں (یعنی عام طور پر شدید معاشرتی یا پیشہ ورانہ خرابی کا سبب نہیں بنتے ہیں ، اور وہ نفسیات کے بغیر ہیں) ، اور اس سے دوئبرووی II کی تشخیص کرنا زیادہ مشکل ہوسکتا ہے ، کیونکہ ہائپو مینک اقساط صرف ادوار کے طور پر ظاہر ہوسکتے ہیں۔کامیاب اعلی پیداوری کی اور تکلیف دہ ، معذور افسردگی سے کم کثرت سے رپورٹ کیا جاتا ہے۔\nسائکلوتھیمیا: افسردگی کے ادوار کے ساتھ ہائپوومینک اقساط کی ایک تاریخ جو بڑے افسردگی کے واقعات کے معیار پر پورا نہیں اترتی۔ [10]', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'نفسیاتی پورٹلپسیولوجی پورٹل میڈیسن پورٹل'),
(23, 'دماغی صحت', 'علامات نہیں مل پائے۔', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(24, 'اقسام', 'علامات نہیں مل پائے۔', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(25, 'نشانات و علامات', 'مشترکہ شمولیت ، میٹاکارپوفالنجیل جوڑ ، قربت سے انٹرفالنجیل جوڑ ، انگوٹھے کا انٹرفالنجیل جوائنٹ ، دوسرے نمبر پر پانچویں میٹاتارسوفالنجیل جوائنٹ اور کلائی کے ذریعہ چھوٹے جوڑوں ، اور کندھوں ، کوہنیوں ، ہپ جوڑوں ، گھٹنوں اور ٹخنوں کی طرح بڑے جوڑوں کی حیثیت سے ،\n1 بڑے مشترکہ کی شمولیت 0 پوائنٹس دیتی ہے\n2-10 بڑے جوڑوں کی شمولیت 1 پوائنٹ دیتی ہے\n1–3 چھوٹے جوڑوں کی شمولیت (بڑے جوڑوں کی شمولیت کے ساتھ یا اس کے بغیر) 2 پوائنٹس دیتی ہے\n4-10 چھوٹے جوڑوں کی شمولیت (بڑے جوڑوں کی شمولیت کے ساتھ یا اس کے بغیر) 3 پوائنٹس دیتی ہے\n10 سے زیادہ جوڑوں کی شمولیت (کم از کم 1 چھوٹے مشترکہ کی شمولیت کے ساتھ) 5 پوائنٹس دیتی ہے\nسیرولوجیکل پیرامیٹرز-بشمول ریمیٹائڈ عنصر کے ساتھ ساتھ ACPA-\"ACPA\" کا مطلب ہے \"اینٹی سائٹرولینیٹڈ پروٹین اینٹی باڈی\":\nمنفی آریف اور منفی ACPA 0 پوائنٹس دیتا ہے\nکم مثبت آر ایف یا کم مثبت ACPA 2 پوائنٹس دیتا ہے\nاعلی مثبت آر ایف یا اعلی مثبت ACPA 3 پوائنٹس دیتا ہے\nشدید مرحلے کے ری ایکٹنٹس: بلند اریتھروسائٹ تلچھٹ کی شرح ، ESR ، یا بلند CRP ویلیو (C-Rective پروٹین) کے لئے 1 پوائنٹ\nگٹھیا کی مدت: چھ ہفتوں یا اس سے زیادہ عرصے تک چلنے والی علامات کے لئے 1 نقطہ', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(26, 'نشانات و علامات', 'الکاپٹنوریا [24]\nجوڑوں کے پیدائشی عوارض [25] [26]\nذیابیطس اوسٹیو ارتھرائٹس کی وجہ سے مشترکہ متبادل ہونے کے خطرے کو دوگنا کرتا ہے اور ذیابیطس کے شکار افراد ذیابیطس والے افراد کی نسبت چھوٹی عمر میں مشترکہ تبدیلی رکھتے ہیں۔ [27]\nایہلرز ڈینلوس سنڈروم [28]\nہیموچروومیٹوسس اور ولسن کی بیماری [29]\nسوزش کی بیماریوں (جیسے پرتھیس کی بیماری) ، (لائم بیماری) ، اور گٹھیا کی تمام دائمی شکلیں (جیسے ، کاسٹوکونڈرائٹس ، گاؤٹ ، اور ریمیٹائڈ گٹھیا)۔گاؤٹ میں ، یورک ایسڈ کرسٹل کارٹلیج کو تیز رفتار سے انحطاط کا باعث بنتے ہیں۔\nکسی حادثے یا آرتھوپیڈک کارروائیوں کے نتیجے میں جوڑوں یا ligaments (جیسے ACL) کو چوٹ پہنچا۔\nligamentous بگاڑ یا عدم استحکام ایک عنصر ہوسکتا ہے۔\nمارفن سنڈروم [30]\nموٹاپا [31]\nمشترکہ انفیکشن [32] [33] [34]', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'اسٹرونٹیم رینیلیٹ - آسٹیو ارتھرائٹس میں انحطاط کو کم کرسکتا ہے اور نتائج کو بہتر بنا سکتا ہے [200] [201]\nجین تھراپی - جین کی منتقلی کی حکمت عملیوں کا مقصد علامات کے بجائے بیماری کے عمل کو نشانہ بنانا ہے۔ [202]سیل ثالثی جین تھراپی کا بھی مطالعہ کیا جارہا ہ'),
(27, 'نشانات و علامات', 'سینے کا ایکس رے شدید COPD کا مظاہرہ کررہا ہے ، پھیپھڑوں کے مقابلے میں دل کے چھوٹے سائز کو ظاہر کرتا ہے\n\n\n\nایمفیسیما والے شخص کا پس منظر کا سینہ ایکس رے ، بیرل سینے اور فلیٹ ڈایافرام کی نمائش کرتا ہے\n\n\n\nپھیپھڑوں کا بلا جیسا کہ شدید COPD والے شخص میں سینے کے ایکسرے پر دیکھا جاتا ہے\n\n\n\nبدمعاش ایمفیسیما کا ایک سنگین معاملہ\n\n\n\nآخری مرحلے میں بدمعاش ایمفیسیما والے شخص کے پھیپھڑوں کی محوری سی ٹی تصویر\n\n\n\nبائیں طرف پھیپھڑوں کے کینسر کے ساتھ بہت شدید ایمفیسیما (سی ٹی اسکین)', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(28, 'اقسام', 'علامات نہیں مل پائے۔', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'کون قلبی امراض پر فیکٹ شیٹ\nکلینیکل پریکٹس میں قلبی بیماری سے بچاؤ کے بارے میں 2021 ESC کے رہنما خطوط\nدل کی بیماری میڈیسنیٹ سلائیڈز ، تصاویر ، وضاحت\nرسک کیلکولیٹر\nانٹرایکٹو سی وی رسک کیلکولیٹر'),
(29, 'درجہ بندی', 'چہرے کی ہیمپلیگیا اور پٹھوں کی کمزوری\nبے حسی\nحسی یا کمپن سنسنی میں کمی\nابتدائی flaccidity (پٹھوں کے سر کو کم) ، جس کی جگہ spasticity (پٹھوں کے سر میں اضافہ) ، ضرورت سے زیادہ اضطراب اور لازمی ہم آہنگی کی جگہ ہے۔ [] 43]', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(30, 'نشانات و علامات', 'ٹانک-کلونک ،\nٹانک ،\nکلونک ،\nmyoclonic ،\nغیر موجودگی ، اور\nایٹونک دوروں۔ [29]', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(31, 'نشانات و علامات', 'ایم آر آئی کے ساتھ کم از کم 2 کلینیکل حملے جو 2 یا اس سے زیادہ گھاووں کو ایم ایس کی خصوصیت دکھا رہے ہیں۔ [91]\nایم آر آئی کے ساتھ کم از کم 2 کلینیکل حملے جس میں ایم ایس کی 1 گھاووں کی خصوصیت دکھائی گئی ہے جس میں پچھلے حملے کے واضح تاریخی ثبوت موجود ہیں جن میں سی این ایس میں ایک الگ جگہ پر گھاو شامل ہے۔ [91]\nایم آر آئی کے ساتھ کم از کم 2 کلینیکل حملے جو ایم ایس کی 1 گھاووں کی خصوصیت دکھا رہے ہیں ، جس میں ایک الگ سی این ایس سائٹ پر اضافی کلینیکل اٹیک کے ذریعہ یا ایم آر آئی کے ذریعہ ایک پرانے ایم ایس گھاووں کو دکھایا گیا ہے۔ [91]\nایم آر آئی کے ساتھ 1 کلینیکل حملہ جس میں کم از کم 2 گھاووں کو ایم ایس کی خصوصیت دکھائی گئی ہے ، جس میں ایک اضافی حملے کے ذریعہ ڈی آئی ٹی قائم کی گئی ہے ، ایم آر آئی کے ذریعہ پرانے ایم ایس گھاووں کو دکھایا گیا ہے ، یا سی ایس ایف میں اولیگوکلونل بینڈ کی موجودگی۔ [91]\n1 ایم آر آئی کے ساتھ کلینیکل حملہ جس میں ایم ایس کی 1 گھاووں کی خصوصیت دکھائی جارہی ہے ، جس میں کسی مختلف سی این ایس سائٹ پر اضافی حملے کے ذریعہ یا ایم آر آئی کے ذریعہ پرانے ایم ایس گھاووں کو دکھایا گیا ہے ، اور ایک اضافی حملے کے ذریعہ قائم کردہ ڈی آئی ٹی ، ایم آر آئی کے ذریعہ پرانے محترمہ گھاووں کو دکھایا گیا ہے (ایس) ، یا سی ایس ایف میں اولیگوکلونل بینڈ کی موجودگی۔ [91]', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(32, 'نام تنازعہ', 'وی', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'ایکیوپنکچر چین میں سوزش کی آنتوں کی بیماری کے علاج کے لئے استعمال ہوتا ہے ، اور مغربی معاشرے میں زیادہ کثرت سے استعمال ہوتا ہے۔ [228]اس وقت ، ایکیوپنکچر کے استعمال کی سفارش کرنے کے لئے شواہد ناکافی ہیں۔ [227]\nجرمنی میں 2006 کے ایک سروے میں بتایا گیا ہے کہ'),
(33, 'نشانات و علامات', 'وی', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'روبن ڈی ٹی ، اننت کرشنن اے این ، سیگل سی اے ، سوور بی جی ، لانگ ایم ڈی (مارچ 2019)۔\"ACG کلینیکل گائیڈ لائن: بالغوں میں السرٹیو کولائٹس\"۔امریکن جرنل آف گیسٹروینولوجی۔114 (3): 384–413۔doi: 10.14309/AJG.0000000000000152۔PMID 30840605. S2CID 73473272۔\nٹورپی ج'),
(34, 'نشانات و علامات', 'کاربوہائیڈریٹ اور چربی کی خرابی سے وزن کم ہونے کا سبب بن سکتا ہے (یا بچوں میں پھل پھولنے یا تیز تر نمو میں ناکامی) اور تھکاوٹ یا توانائی کی کمی کا سبب بن سکتا ہے۔\nخون کی کمی سے کئی طریقوں سے ترقی ہوسکتی ہے: آئرن مالابسورپشن آئرن کی کمی کی کمی کا سبب بن سکتی ہے ، اور فولک ایسڈ اور وٹامن بی 12 مالابسورپشن میگالوبلاسٹک انیمیا کو جنم دے سکتا ہے۔\nکیلشیم اور وٹامن ڈی مالابسورپشن (اور معاوضہ ثانوی ہائپرپیریٹائیرائڈزم) آسٹیوپینیا (ہڈی کے معدنی مواد میں کمی) یا آسٹیوپوروسس (ہڈیوں کو کمزور کرنے اور نزاکت فریکچر کا خطرہ) کا سبب بن سکتا ہے۔\nسیلیک بیماری میں سیلینیم مالابسورپشن ، بہت سے گلوٹین فری فوڈز میں کم سیلینیم مواد کے ساتھ مل کر ، سیلینیم کی کمی کا خطرہ مول دیتا ہے۔ [] २]\nتانبے اور زنک کی کمی کو بھی سیلیک بیماری سے وابستہ کیا گیا ہے۔ [] २]\nوٹامن کے کی کمی کی وجہ سے لوگوں کا ایک چھوٹا سا تناسب غیر معمولی کوگولیشن ہوتا ہے اور اسے غیر معمولی خون بہنے کا معمولی خطرہ ہوتا ہے۔', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(35, 'نشانات و علامات', 'رینن - انجیوٹینسن سسٹم کے توسط سے گردے کے ذریعہ تیار کردہ سیال اوورلوڈ اور واسوویکٹیو ہارمونز کی پیداوار کی وجہ سے بلڈ پریشر میں اضافہ ہوا ہے ، جس سے ہائی بلڈ پریشر اور دل کی ناکامی کا خطرہ بڑھ جاتا ہے۔سی کے ڈی والے افراد عام آبادی کے مقابلے میں زیادہ امکان رکھتے ہیں کہ اس کے نتیجے میں قلبی امراض کے ساتھ ایٹروسکلروسیس پیدا ہوسکے ، یہ ایک ایسا اثر ہے جو کم از کم جزوی طور پر یوریمک ٹاکسن کے ذریعہ ثالثی کی جاسکتی ہے۔صرف قلبی بیماری سے دوچار افراد کے مقابلے میں تشخیص۔ [25]\nیوریا جمع ہوتا ہے ، جس کی وجہ سے ازوٹیمیا اور بالآخر یوریا ہوتا ہے (سستی سے لے کر پیریکارڈائٹس اور انسیفالوپیتھی تک کی علامات)۔اس کی اعلی سیسٹیمیٹک حراستی کی وجہ سے ، یوریا اعلی حراستی پر ایککرین پسینے میں خارج ہوتا ہے اور پسینے کے بخارات (\"یوریمک فراسٹ\") کے ساتھ ہی جلد پر کرسٹالائز ہوتا ہے۔\nپوٹاشیم خون میں جمع ہوتا ہے (ہائپرکلیمیا جس میں علامات کی ایک حد ہوتی ہے جس میں خرابی اور ممکنہ طور پر مہلک کارڈیک اریٹھیمیاس شامل ہیں)۔ہائپرکلیمیا عام طور پر اس وقت تک ترقی نہیں کرتا جب تک کہ گلوومیرولر فلٹریشن کی شرح 20-25 ملی لیٹر/منٹ/منٹ/1.73 ایم 2 سے بھی کم نہ آجائے ، جب گردوں میں پوٹاشیم خارج ہونے کی صلاحیت میں کمی واقع ہوتی ہے۔سی کے ڈی میں ہائپرکلیمیا کو تیزابیت سے بڑھایا جاسکتا ہے (تیزاب کو بے اثر کرنے کے لئے خلیوں کو خون کے دھارے میں پوٹاشیم کو جاری کرنے کے لئے خلیوں کو متحرک کرنا) اور انسولین کی کمی سے۔ [26]\nسیال اوورلوڈ کی علامات ہلکے ورم میں کمی لانے سے لے کر جان لیوا پلمونری ورم میں کمی لاتی ہیں۔\nہائپر فاسفیٹیمیا کا نتیجہ گردے میں ناقص فاسفیٹ کے خاتمے سے ہوتا ہے ، اور عروقی کیلکیکیشن کا سبب بن کر قلبی خطرہ میں اضافہ کرنے میں معاون ہے۔ [२२]فبروبلاسٹ گروتھ فیکٹر -23 (ایف جی ایف -23) کی گردش کرنے والی حراستی میں آہستہ آہستہ اضافہ ہوتا ہے کیونکہ فاسفیٹ کے اخراج کے لئے گردے کی گنجائش میں کمی واقع ہوتی ہے ، جو سی کے ڈی والے لوگوں میں بائیں ویںٹرکولر ہائپر ٹرافی اور اموات میں اضافہ کرنے میں معاون ثابت ہوسکتی ہے۔ [28] [29]\nہائپوکالسیمیا کے نتیجے میں 1،25 ڈائی ہائڈروکسیوٹامن ڈی 3 کی کمی (اعلی ایف جی ایف -23 اور گردے کے بڑے پیمانے پر کم ہونے کی وجہ سے) [30] اور پیراٹائیرائڈ ہارمون کی کارروائی کی مزاحمت کا نتیجہ ہے۔ [31]اوسٹیوسائٹس ایف جی ایف -23 کی بڑھتی ہوئی پیداوار کے لئے ذمہ دار ہیں ، جو انزائم 1 الفا-ہائڈروکسیلیسیس (25-hydroxycholecalciferol 1،25 dihydroxyvitamin D3 میں تبدیل کرنے کے لئے ذمہ دار ہے) کا ایک مضبوط روک تھام ہے۔ [32]بعد میں ، یہ ثانوی ہائپرپیریٹائیرائڈزم ، گردے کے آسٹیوڈسٹروفی ، اور عروقی کیلکیکیشن کی طرف بڑھتا ہے جو کارڈیک فنکشن کو مزید متاثر کرتا ہے۔ایک انتہائی نتیجہ یہ ہے کہ کیلکیلیفیلیکس نامی نایاب حالت کا واقعہ ہے۔ [] 33]\nمعدنیات اور ہڈیوں کے تحول میں تبدیلیاں جو 1) کیلشیم ، فاسفورس (فاسفیٹ) ، پیراٹائیرائڈ ہارمون ، یا وٹامن ڈی میٹابولزم کی اسامانیتاوں کا سبب بن سکتی ہیں۔2) ہڈیوں کے کاروبار ، معدنیات ، حجم ، لکیری نمو ، یا طاقت (گردے آسٹیوڈسٹروفی) میں اسامانیتاوں ؛اور 3) عروقی یا دیگر نرم ٹشو کیلکیکیشن۔ [11]سی کے ڈی-معدنیات اور ہڈیوں کی خرابی خراب نتائج سے وابستہ ہے۔ [11] [21]\nمیٹابولک ایسڈوسس کے نتیجے میں قریبی نلیوں کے خلیوں سے کافی امونیا پیدا کرنے کی صلاحیت میں کمی واقع ہوسکتی ہے۔ [26]تیزابیت خامروں کے کام کو متاثر کرتی ہے اور ہائپرکلیمیا کے فروغ سے کارڈیک اور نیورونل جھلیوں کی جوش و خروش کو بڑھاتا ہے۔ [34]\nانیمیا عام ہے اور خاص طور پر ان لوگوں میں عام ہے جو ہیموڈالیسیس کی ضرورت ہوتی ہے۔یہ وجہ میں ملٹی فیکٹوریل ہے ، لیکن اس میں سوزش میں اضافہ ، اریتھروپائٹین میں کمی ، اور ہائپروریسیمیا شامل ہے جس کی وجہ سے ہڈیوں کا میرو دباؤ پڑتا ہے۔ہائپوپرولیفریٹو انیمیا گردوں کے ذریعہ اریتھروپائٹین کی ناکافی پیداوار کی وجہ سے ہوتا ہے۔ [35]\nبعد کے مراحل میں ، کیچیکسیا ترقی کرسکتا ہے ، جس کی وجہ سے وزن میں کمی ، پٹھوں کو ضائع کرنا ، کمزوری اور کشودا پیدا ہوتا ہے۔ [] 36]\nسی کے ڈی کا سامنا کرنے والے مریضوں میں علمی کمی ایک ابھرتی ہوئی علامت ہے جو تحقیقی ادب میں انکشاف ہوئی ہے۔ [37] [38] [38] [39] [40]موجودہ تحقیق سے پتہ چلتا ہے کہ سی کے ڈی والے مریضوں کو علمی زوال اور یا ڈیمینشیا کے 35-40 ٪ زیادہ امکان کا سامنا کرنا پڑتا ہے۔ [] 37] [38]یہ تعلق ہر مریض میں سی کے ڈی کی شدت پر منحصر ہے۔اگرچہ ابھرتے ہوئے ادب سے یہ ظاہر ہوتا ہے کہ سی کے ڈی کے ہر مراحل میں مریضوں کو ان علمی امور کی نشوونما کا زیادہ خطرہ ہوگا۔ [40] [41] [38]\nسی کے ڈی والے مرد اور خواتین دونوں میں جنسی عدم استحکام بہت عام ہے۔مردوں کی اکثریت میں جنسی ڈرائیو کم ہوتی ہے ، کھڑا کرنے میں دشواری ، اور orgasm تک پہنچ جاتی ہے ، اور عمر کے ساتھ ہی مسائل خراب ہوتے جاتے ہیں۔زیادہ تر خواتین کو جنسی جوش و خروش سے پریشانی ہوتی ہے ، اور تکلیف دہ ماہواری اور جنسی کارکردگی اور لطف اندوز ہونے میں دشواری عام ہے۔ [] २]', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(36, 'درجہ بندی', 'بون میرو کی معافی لانے کے لئے انڈکشن کیموتھریپی۔بڑوں کے ل standard ، معیاری انڈکشن منصوبوں میں پریڈیسون ، ونکرسٹائن ، اور ایک اینتھراسائکلائن دوائی شامل ہیں۔منشیات کے دیگر منصوبوں میں L-asparaginase یا cyclophosphamide شامل ہوسکتے ہیں۔کم خطرہ والے بچوں کے لئے ، معیاری تھراپی عام طور پر علاج کے پہلے مہینے کے لئے تین منشیات (پریڈیسون ، ایل-اسپرگینیز ، اور ونسکریسٹین) پر مشتمل ہوتی ہے۔\nکسی بھی باقی لیوکیمیا خلیوں کو ختم کرنے کے لئے استحکام تھراپی یا شدت تھراپی۔استحکام کے ل many بہت سے مختلف نقطہ نظر موجود ہیں ، لیکن یہ عام طور پر ایک اعلی خوراک ، ملٹی منشیات کا علاج ہے جو کچھ مہینوں کے لئے کیا جاتا ہے۔کم سے اوسط خطرہ والے افراد اینٹی میٹابولائٹ دوائیوں جیسے میتھوٹریکسٹیٹ اور 6-مرکپٹپورین (6-ایم پی) کے ساتھ تھراپی حاصل کرتے ہیں۔جن لوگوں کو زیادہ خطرہ ہے وہ ان دوائیوں کی زیادہ مقدار میں منشیات کے علاوہ اضافی دوائیں وصول کرتے ہیں۔\nاعلی خطرے والے لوگوں میں دماغ اور اعصابی نظام میں پھیلنے سے کینسر کو روکنے کے لئے سی این ایس پروفیلیکسس (بچاؤ تھراپی)۔معیاری پروفیلیکسس میں سر کی تابکاری اور/یا منشیات کو براہ راست ریڑھ کی ہڈی میں پہنچایا جاسکتا ہے۔\nایک بار معافی حاصل ہونے کے بعد بیماری کی تکرار کو روکنے کے لئے کیموتھراپیٹک دوائیوں کے ساتھ بحالی کے علاج۔بحالی کی تھراپی میں عام طور پر منشیات کی کم مقدار شامل ہوتی ہے اور یہ تین سال تک جاری رہ سکتی ہے۔\nمتبادل کے طور پر ، اللوجینک بون میرو ٹرانسپلانٹیشن اعلی خطرہ یا دوبارہ منسلک لوگوں کے لئے موزوں ہوسکتا ہے۔ [] २]', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(37, 'نشانات و علامات', 'لیمفاڈینوپیتھی [20] [21] یا لمف نوڈس کی سوجن ، لمفوما میں بنیادی پیش کش ہے۔یہ عام طور پر بے درد ہے۔\nبی علامات (سیسٹیمیٹک علامات)-ہڈکنکن لیمفوما اور نان ہڈکن لیمفوما دونوں سے وابستہ ہوسکتے ہیں۔وہ پر مشتمل ہیں:\nبخار [20] [21]\nرات کے پسینے [20] [21]\nوزن میں کمی [20] [21]\nدیگر علامات:\nانیمیا ، خون بہہ رہا ہے ، انفیکشن کی حساسیت میں اضافہ [22]\nبھوک یا کشودا کا نقصان [21]\nتھکاوٹ [20] [21]\nسانس کی تکلیف یا dyspnea [21]\nخارش [20] [21]', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(38, 'نشانات و علامات', 'psoriasis کی تختی\n\n\n\nایک شخص کا بازو تختی psoriasis سے ڈھکا ہوا ہے\n\n\n\nہتھیلیوں کا psoriasis', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(39, 'نشانات و علامات', 'ہلکی جلد پر وٹیلیگو\n\n\n\nسیاہ جلد پر غیر طبقاتی وٹیلیگو\n\n\n\nپلکیں کا غیر طبقاتی وٹیلیگو', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(40, 'نشانات و علامات', 'غیر متناسب\nبارڈرز (کناروں اور کونوں کے ساتھ فاسد)\nرنگ (مختلف)\nقطر (6 ملی میٹر سے زیادہ (0.24 انچ) ، پنسل صاف کرنے والے کے سائز کے بارے میں)\nوقت کے ساتھ ساتھ تیار ہوتا ہے', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(41, 'تاریخ', 'تین ماہ سے زیادہ عرصے تک جاری رہنے والے بڑے درد کی ایک تاریخ - جسم کے چاروں چوکوروں کو متاثر کرتی ہے ، یعنی ، دونوں اطراف اور کمر کے اوپر اور نیچے۔\nٹینڈر پوائنٹس - یہاں 18 نامزد کردہ ٹینڈر پوائنٹس ہیں (حالانکہ اس عارضے میں مبتلا شخص دوسرے علاقوں میں بھی درد محسوس کرسکتا ہے)۔', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(42, 'نشانات و علامات', 'dysmenorrea (64 ٪) [21] - ماہواری کے دوران تکلیف دہ ، بعض اوقات درد کو غیر فعال کرنا ؛درد وقت (ترقی پسند درد) کے ساتھ بدتر ہوسکتا ہے ، کمر کے کم درد بھی شرونی سے منسلک ہوتا ہے\nدائمی شرونیی درد - عام طور پر کم پیٹھ میں درد یا پیٹ میں درد کے ساتھ\ndyspareunia - تکلیف دہ جنسی جماع\nڈیسوریا - پیشاب کی عجلت ، تعدد ، اور بعض اوقات تکلیف دہ آواز [22]\nمٹیلسلچمرز - ovulation سے وابستہ درد [23]\nجسمانی حرکت میں درد - ورزش ، کھڑے ہونے یا چلنے کے دوران موجود [22]', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(43, 'تعریف', 'ماہواری کی خرابی: پی سی او ایس زیادہ تر اولیگومینوریا (ایک سال میں نو سے کم ماہواری سے کم) یا امینوریا (تین یا زیادہ مہینوں تک ماہواری کی مدت نہیں) پیدا کرتا ہے ، لیکن ماہواری کی دیگر اقسام بھی ہوسکتی ہیں۔ [22]\nبانجھ پن: یہ عام طور پر براہ راست دائمی انوولیشن (ovulation کی کمی) سے نکلتا ہے۔ [22]\nمردانہ شکل دینے والے ہارمونز کی اعلی سطح: ہائپرینڈروجنزم کے نام سے جانا جاتا ہے ، سب سے عام علامتیں مہاسوں اور ہرسوٹزم (بالوں کی نشوونما کا مردانہ نمونہ ، جیسے ٹھوڑی یا سینے پر) ہیں ، لیکن اس سے ہائپرمینوریا (بھاری اور طویل ماہواری کے ادوار) ، اینڈروجینک الوپیسیا پیدا ہوسکتا ہے (بالوں کی پتلی یا پھیلا ہوا بالوں کے گرنے میں اضافہ) ، یا دیگر علامات۔ [22] [29]پی سی او ایس والی تقریبا three تین چوتھائی خواتین (NIH/NICHD 1990 کے تشخیصی معیار کے مطابق) ہائپرینڈروجینیمیا کے ثبوت ہیں۔ [30]\nمیٹابولک سنڈروم: یہ مرکزی موٹاپا اور انسولین مزاحمت سے وابستہ دیگر علامات کی طرف رجحان کے طور پر ظاہر ہوتا ہے ، جس میں کم توانائی کی سطح اور کھانے کی خواہش شامل ہے۔ [22]پی سی او ایس والی خواتین میں سیرم انسولین ، انسولین مزاحمت ، اور ہومو سسٹین کی سطح زیادہ ہے۔ [31]\nمہاسے: ٹیسٹوسٹیرون کی سطح میں اضافے سے ، سیباسیئس غدود اور چھیدوں کے اندر تیل کی پیداوار میں اضافہ ہوتا ہے۔ [32]بہت سارے لوگوں کے لئے ، جذباتی اثر بہت اچھا ہے اور زندگی کے معیار کو نمایاں طور پر کم کیا جاسکتا ہے۔ [] 33]\nandrogenic alopecia: تخمینے سے پتہ چلتا ہے کہ androgenic alopecia 22 ٪ PCOS میں مبتلا افراد کو متاثر کرتا ہے۔ [32]یہ اعلی ٹیسٹوسٹیرون کی سطح کا نتیجہ ہے جو ڈائی ہائڈروٹیسٹوسٹیرون (ڈی ایچ ٹی) ہارمون میں تبدیل ہوتا ہے۔بالوں کے پٹک بھری ہوجاتے ہیں ، جس سے بال گر جاتے ہیں اور مزید نمو کو روکتے ہیں۔ [34]\nاکانتھوسس نگیرکینز (اے این): جلد کی ایک ایسی حالت جہاں سیاہ ، موٹی اور \"مخمل\" پیچ بن سکتے ہیں۔(صفحہ 141) [35]\nپولی سائسٹک انڈاشی: پی سی او ایس ایک پیچیدہ عارضہ ہے جس کی خصوصیات اعلی اینڈروجن کی سطح ، فاسد حیض ، اور/یا ایک یا دونوں انڈاشیوں پر چھوٹے چھوٹے سسٹس کی ہوتی ہے۔انڈاشیوں میں توسیع ہوسکتی ہے اور انڈوں کے آس پاس کے follicles پر مشتمل ہوتا ہے۔اس کے نتیجے میں ، انڈاشی باقاعدگی سے کام کرنے میں ناکام ہوسکتی ہے۔یہ بیماری ہر ماہ انڈاشیوں کی تعداد سے متعلق ہے جس میں ہر ماہ اوسطا 6-8 سے دوگنا ، ٹرپل یا اس سے زیادہ [حوالہ درکار] تک بڑھتا ہے۔پی سی او ایس والی خواتین میں بانجھ پن ، ٹائپ 2 ذیابیطس میلیتس (ڈی ایم -2) ، قلبی خطرہ ، میٹابولک سنڈروم ، موٹاپا ، خراب گلوکوز رواداری ، افسردگی ، رکاوٹ نیند اپنیا (او ایس اے) ، اینڈومیٹریال فیٹی کینسر ، اور نانلکلیوکولک فیٹی لیور سمیت متعدد بیماریوں کا زیادہ خطرہ ہوتا ہے۔بیماری/غیر الکحل اسٹیٹو ہیپیٹائٹس (NAFLD/NASH)۔ [36]', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'دوا نہیں ملی۔'),
(44, 'نشانات و علامات', 'کسی کی عمر اور اونچائی کے لئے ایک کم جسمانی ماس انڈیکس (سوائے \"atypical anorexia\" کے معاملات میں) [26]\nفاسد یا غیر حاضر ماہواری [27] ادوار\nخشک بالوں اور جلد ، بالوں کی پتلی ، نیز بالوں کا گرنا [28]\nہر وقت سردی محسوس ہوتی ہے (ہائپوتھرمیا) [29]\nتیز ، وزن میں کمی [30]\nمعدے کی بیماری [31]\nہائپوٹینشن یا آرتھوسٹٹک ہائپوٹینشن\nبریڈی کارڈیا یا ٹکی کارڈیا\nرسل کی علامت ؛ہاتھ کے پچھلے حصے پر خروںچ کے ساتھ خود حوصلہ افزائی الٹی کی ایک کہانی کی علامت ہوسکتی ہے\nدائمی تھکاوٹ [32]\nبانجھ پن\nہالیٹوسس (الٹی یا فاقہ کشی سے متاثرہ کیٹوسس سے)\nپٹھوں میں شدید تناؤ ، درد اور تکلیف ہے\nنیند نہ آنا\nپیٹ میں خلل\nلاناگو: چہرے اور جسم پر نرم ، عمدہ بال بڑھ رہے ہیں [] 33]\nجلد کی سنتری کی رنگت ، خاص طور پر پاؤں (کیروٹینوسس)', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'جسم کی تصویر\nکھانے کی بازیابی\nارتقائی نفسیات\nidée fixe\ninedia\nکشودا نرووسا کے ساتھ لوگوں کی فہرست\nنیشنل ایسوسی ایشن آف انوریکسیا نیرووسہ اور اس سے وابستہ عوارض\nپٹھوں ڈیسمورفیا\nآرتھوریکسیا نیروسہ\nپرو-این اے'),
(45, 'نشانات و علامات', 'کھانے کے بعد دائمی گیسٹرک ریفلوکس ، الٹی سے ثانوی [15]\nپانی کی کمی اور ہائپوکلیمیا الکلوسیس اور بار بار الٹی کی موجودگی میں گردوں کے پوٹاشیم نقصان کی وجہ سے [16]\nالیکٹرولائٹ عدم توازن دل کی غیر معمولی تال ، کارڈیک گرفتاری ، اور یہاں تک کہ موت کا باعث بن سکتا ہے\nغذائی نالی ، یا غذائی نالی کی سوزش\nمیلوری ویس آنسو\nبوئیرہاو سنڈروم ، الٹی کی وجہ سے غذائی نالی کی دیوار میں پھٹ جانا\nزبانی صدمہ ، جس میں انگلیوں یا دیگر اشیاء کی بار بار داخل کرنا منہ یا گلے کے استر میں لیسریشن کا سبب بنتا ہے\nرسل کا اشارہ: انیسیسرز کی طرف سے بار بار صدمے کی وجہ سے نکلز اور ہاتھوں کے پچھلے حصے پر کالس [17] [18]\nپیریمولیسس ، یا دانتوں کے تامچینی کے دانتوں کا شدید کٹاؤ [19]\nسوجن تھوک کے غدود (مثال کے طور پر ، گردن میں ، جبڑے کے نیچے) [19] [20]\nگیسٹروپریسیس ، یا گیسٹرک خالی ہونے میں تاخیر\nقبض یا اسہال\ntachycardia یا دھڑکن\nہائپوٹینشن\nپیپٹک السر\nبانجھ پن\nوزن کے مستقل اتار چڑھاو عام ہیں\nبلند بلڈ شوگر ، کولیسٹرول ، اور امیلیس کی سطح ہوسکتی ہے\nہائپوگلیسیمیا الٹی ہونے کے بعد ہوسکتا ہے', 'احتیاطی تدابیر نہیں ملی۔', 'روک تھام کے طریقے نہیں ملے۔', 'anorectic طرز عمل مشاہدہ اسکیل\nکھانے کی بازیابی\nارتقائی نفسیات\nپرخوری کی بیماری\nبلیمیا نیروسہ والے لوگوں کی فہرست'),
(46, 'میلانوما', 'تل جو سائز میں بڑھ رہا ہے ، اس میں فاسد کناروں ، رنگ ، خارش یا جلد کی خرابی میں تبدیلی ہے۔ [1]', 'سنسکرین ، یووی لائٹ سے گریز کرنا [2]', 'میلانوما کے لئے بالغوں کی آبادی کی اسکریننگ کی حمایت کرنے یا ان کی تردید کرنے کے لئے کوئی ثبوت نہیں ہے۔ [] 93]', 'antimalarial دوا نہیں ملی۔'),
(47, 'میلانوما', 'میلانوما کی ابتدائی علامتیں موجودہ مولوں کی شکل یا رنگ میں تبدیل ہوتی ہیں یا ، نوڈولر میلانوما کی صورت میں ، جلد پر کہیں بھی ایک نئے گانٹھ کی ظاہری شکل ہوتی ہیں۔بعد کے مراحل میں ، تل خارش ، السریٹ یا خون بہہ سکتا ہے۔میلانوما کی ابتدائی علامتوں کا خلاصہ میمونک \"ABCDEEFG\" کے ذریعہ کیا گیا ہے: [14] [15]', 'میلانوما کے لئے بالغوں کی آبادی کی اسکریننگ کی حمایت کرنے یا ان کی تردید کرنے کے لئے کوئی ثبوت نہیں ہے۔ [] 93]', 'میلانوما کے لئے بالغوں کی آبادی کی اسکریننگ کی حمایت کرنے یا ان کی تردید کرنے کے لئے کوئی ثبوت نہیں ہے۔ [] 93]', 'کلینیکل تشخیص کی تصدیق جلد کے بایڈپسی کے ساتھ کی جاتی ہے۔اس کی پیروی عام طور پر داغ یا ٹیومر کی وسیع پیمانے پر کی جاتی ہے۔اسٹیج پر منحصر ہے ، ایک سینٹینیل لمف نوڈ بایپسی انجام دی جاسکتی ہے۔سینٹینل لمف نوڈ بایڈپسی کے آزمائشی ثبوت کے آس پاس تنازعہ موجود ہے۔'),
(48, 'ذہنی عارضہ', 'نفسیاتی عوارض کا آغاز عام طور پر بچپن سے ابتدائی جوانی تک ہوتا ہے۔ [] 54]بچپن میں تسلسل پر قابو پانے کی خرابی اور کچھ اضطراب کی خرابی ظاہر ہوتی ہے۔کچھ دیگر اضطراب کی خرابی ، مادے کی خرابی اور موڈ کی خرابی کے بعد بعد میں وسط نو عمر میں ہی سامنے آتے ہیں۔ [] 55]شیزوفرینیا کی علامات عام طور پر دیر سے جوانی سے لے کر بیس کی دہائی تک ظاہر ہوتی ہیں۔ [] 56]', '2004 کے \"ذہنی عوارض کی روک تھام\" کی اطلاع دینے والے نے کہا ہے کہ \"ان عوارض کی روک تھام ظاہر ہے کہ [بیماری] کے بوجھ کو کم کرنے کا ایک مؤثر ترین طریقہ ہے۔\" [110]\nذہنی عوارض کی روک تھام کے بارے میں 2011 کے یورپی نفسیاتی ایسوسی ایشن (ای پی اے) کی رہنمائی میں کہا گیا ہے کہ \"اس بات کا کافی ثبوت موجود ہے کہ موثر شواہد پر مبنی مداخلتوں کے نفاذ کے ذریعہ مختلف نفسیاتی حالات کو روکا جاسکتا ہے۔\" [111]\nذہنی صحت کو فروغ دینے اور ذہنی بیماری سے بچاؤ کے لئے معاشی معاملے سے متعلق 2011 کے برطانیہ کے محکمہ صحت کی رپورٹ میں بتایا گیا ہے کہ \"بہت ساری مداخلتیں پیسے کے لئے قابل قدر قیمت ہیں ، لاگت کم ہوتی ہیں اور وقت کے ساتھ ساتھ اکثر خود مالی اعانت ہوجاتی ہیں۔\"ن\n2016 میں ، نیشنل انسٹی ٹیوٹ آف مینٹل ہیلتھ نے ریسرچ ترجیحی علاقے کے طور پر روک تھام کی روک تھام کی۔ [113]', '2004 کے \"ذہنی عوارض کی روک تھام\" کی اطلاع دینے والے نے کہا ہے کہ \"ان عوارض کی روک تھام ظاہر ہے کہ [بیماری] کے بوجھ کو کم کرنے کا ایک مؤثر ترین طریقہ ہے۔\" [110]\nذہنی عوارض کی روک تھام کے بارے میں 2011 کے یورپی نفسیاتی ایسوسی ایشن (ای پی اے) کی رہنمائی میں کہا گیا ہے کہ \"اس بات کا کافی ثبوت موجود ہے کہ موثر شواہد پر مبنی مداخلتوں کے نفاذ کے ذریعہ مختلف نفسیاتی حالات کو روکا جاسکتا ہے۔\" [111]\nذہنی صحت کو فروغ دینے اور ذہنی بیماری سے بچاؤ کے لئے معاشی معاملے سے متعلق 2011 کے برطانیہ کے محکمہ صحت کی رپورٹ میں بتایا گیا ہے کہ \"بہت ساری مداخلتیں پیسے کے لئے قابل قدر قیمت ہیں ، لاگت کم ہوتی ہیں اور وقت کے ساتھ ساتھ اکثر خود مالی اعانت ہوجاتی ہیں۔\"ن\n2016 میں ، نیشنل انسٹی ٹیوٹ آف مینٹل ہیلتھ نے ریسرچ ترجیحی علاقے کے طور پر روک تھام کی روک تھام کی۔ [113]', 'دوا نہیں ملی۔'),
(49, 'اسٹروک', 'اسٹروک کی علامات عام طور پر اچانک ، سیکنڈ سے منٹ سے زیادہ شروع ہوتی ہیں ، اور زیادہ تر معاملات میں مزید ترقی نہیں ہوتی ہے۔علامات متاثرہ دماغ کے علاقے پر منحصر ہیں۔دماغ کا جتنا وسیع علاقہ متاثر ہوتا ہے ، اتنا ہی زیادہ افعال جو ضائع ہونے کا امکان رکھتے ہیں۔فالج کی کچھ شکلیں اضافی علامات کا سبب بن سکتی ہیں۔مثال کے طور پر ، انٹرایکرنیل ہیمرج میں ، متاثرہ علاقے دوسرے ڈھانچے کو کمپریس کرسکتے ہیں۔فالج کی زیادہ تر شکلیں سر درد کے ساتھ وابستہ نہیں ہیں ، اس کے علاوہ سبرچنائڈ ہیمرج اور دماغی وینس کے تھرومبوسس اور کبھی کبھار انٹرایسیریبرل ہیمرج۔ [32]', 'فالج کے مرض کے بوجھ کو دیکھتے ہوئے ، روک تھام صحت عامہ کی ایک اہم تشویش ہے۔ [] 83]بنیادی روک تھام ثانوی روک تھام سے کم موثر ہے (جیسا کہ ہر سال ایک فالج کو روکنے کے لئے علاج کرنے کے لئے درکار تعداد کے مطابق سمجھا جاتا ہے)۔ [] 83]حالیہ رہنما خطوط میں فالج میں بنیادی روک تھام کے شواہد کی تفصیل ہے۔ [] 84]فالج کے ل a ایک احتیاطی دوائی کے طور پر اسپرین کے استعمال کے بارے میں ، صحت مند افراد میں اسپرین فائدہ مند نہیں دکھائی دیتا ہے اور اس طرح اس کی سفارش نہیں کی جاتی ہے ، [] 85] لیکن اعلی قلبی خطرہ والے لوگوں میں ، یا جن لوگوں کو مایوکارڈیل انفکشن ہوا ہے ، اس سے کچھ تحفظ فراہم ہوتا ہے۔پہلے فالج کے خلاف۔ [] 86] [] 87]ان لوگوں میں جو پہلے فالج کر چکے ہیں ، اسپرین ، کلوپیڈوگریل ، اور ڈپائرڈامول جیسی دوائیوں سے علاج فائدہ مند ثابت ہوسکتا ہے۔ [] 86]امریکی بچاؤ خدمات ٹاسک فورس (یو ایس پی ایس ٹی ایف) علامات کے بغیر ان میں کیروٹائڈ دمنی اسٹینوسس کی اسکریننگ کے خلاف سفارش کرتی ہے۔ [] 88]', 'فالج کے مرض کے بوجھ کو دیکھتے ہوئے ، روک تھام صحت عامہ کی ایک اہم تشویش ہے۔ [] 83]بنیادی روک تھام ثانوی روک تھام سے کم موثر ہے (جیسا کہ ہر سال ایک فالج کو روکنے کے لئے علاج کرنے کے لئے درکار تعداد کے مطابق سمجھا جاتا ہے)۔ [] 83]حالیہ رہنما خطوط میں فالج میں بنیادی روک تھام کے شواہد کی تفصیل ہے۔ [] 84]فالج کے ل a ایک احتیاطی دوائی کے طور پر اسپرین کے استعمال کے بارے میں ، صحت مند افراد میں اسپرین فائدہ مند نہیں دکھائی دیتا ہے اور اس طرح اس کی سفارش نہیں کی جاتی ہے ، [] 85] لیکن اعلی قلبی خطرہ والے لوگوں میں ، یا جن لوگوں کو مایوکارڈیل انفکشن ہوا ہے ، اس سے کچھ تحفظ فراہم ہوتا ہے۔پہلے فالج کے خلاف۔ [] 86] [] 87]ان لوگوں میں جو پہلے فالج کر چکے ہیں ، اسپرین ، کلوپیڈوگریل ، اور ڈپائرڈامول جیسی دوائیوں سے علاج فائدہ مند ثابت ہوسکتا ہے۔ [] 86]امریکی بچاؤ خدمات ٹاسک فورس (یو ایس پی ایس ٹی ایف) علامات کے بغیر ان میں کیروٹائڈ دمنی اسٹینوسس کی اسکریننگ کے خلاف سفارش کرتی ہے۔ [] 88]', 'دوا نہیں ملی۔'),
(50, 'انفیکشن', 'انفیکشن کی علامات اور علامات بیماری کی قسم پر منحصر ہیں۔انفیکشن کی کچھ علامتیں عام طور پر پورے جسم کو متاثر کرتی ہیں ، جیسے تھکاوٹ ، بھوک میں کمی ، وزن میں کمی ، بخار ، رات کے پسینے ، سردیوں ، درد اور درد۔دوسرے جسم کے انفرادی حصوں ، جیسے جلد کی جلدی ، کھانسی ، یا بہتی ہوئی ناک سے مخصوص ہیں۔ [10]', 'ہاتھ دھونے ، گاؤن پہننے ، اور چہرے کے ماسک پہننے جیسی تکنیک انفیکشن کو ایک شخص سے دوسرے میں جانے سے روکنے میں مدد کرسکتی ہے۔19 ویں صدی کے آخر میں طب اور سرجری میں ایسپٹک تکنیک متعارف کروائی گئی تھی اور سرجری کی وجہ سے ہونے والے انفیکشن کے واقعات کو بہت کم کردیا گیا تھا۔ناپسندیدہ حیاتیات کے پھیلاؤ کے خلاف بار بار ہاتھ دھونے کا سب سے اہم دفاع ہے۔ [] 67]روک تھام کی دوسری شکلیں ہیں جیسے غیر قانونی منشیات کے استعمال سے گریز کرنا ، کنڈوم استعمال کرنا ، دستانے پہننا ، اور متوازن غذا اور باقاعدہ ورزش کے ساتھ صحت مند طرز زندگی رکھنا۔کھانے پینے کی اشیاء کو اچھی طرح سے کھانا پکانا اور طویل عرصے سے باہر رہنے والے کھانے سے پرہیز کرنا بھی ضروری ہے۔ [حوالہ کی ضرورت]', 'ہاتھ دھونے ، گاؤن پہننے ، اور چہرے کے ماسک پہننے جیسی تکنیک انفیکشن کو ایک شخص سے دوسرے میں جانے سے روکنے میں مدد کرسکتی ہے۔19 ویں صدی کے آخر میں طب اور سرجری میں ایسپٹک تکنیک متعارف کروائی گئی تھی اور سرجری کی وجہ سے ہونے والے انفیکشن کے واقعات کو بہت کم کردیا گیا تھا۔ناپسندیدہ حیاتیات کے پھیلاؤ کے خلاف بار بار ہاتھ دھونے کا سب سے اہم دفاع ہے۔ [] 67]روک تھام کی دوسری شکلیں ہیں جیسے غیر قانونی منشیات کے استعمال سے گریز کرنا ، کنڈوم استعمال کرنا ، دستانے پہننا ، اور متوازن غذا اور باقاعدہ ورزش کے ساتھ صحت مند طرز زندگی رکھنا۔کھانے پینے کی اشیاء کو اچھی طرح سے کھانا پکانا اور طویل عرصے سے باہر رہنے والے کھانے سے پرہیز کرنا بھی ضروری ہے۔ [حوالہ کی ضرورت]', 'دوا نہیں ملی۔'),
(51, 'COVID 19', 'علامات نہیں مل پائے۔', 'انفیکشن کے امکانات کو کم کرنے کے حفاظتی اقدامات میں قطرے پلانے ، گھر پر رہنا ، عوام میں ماسک پہننا ، ہجوم کی جگہوں سے گریز کرنا ، دوسروں سے فاصلہ رکھنا ، انڈور خالی جگہوں کو ختم کرنا ، ممکنہ نمائش کے دورانیے کا انتظام کرنا ، [197] صابن اور پانی سے اکثر ہاتھ دھونے میں شامل ہیں۔ [197]اور کم از کم بیس سیکنڈ کے لئے ، سانس کی اچھی حفظان صحت کی مشق کرنا ، اور آنکھوں ، ناک ، یا منہ کو دھوئے ہوئے ہاتھوں سے چھونے سے گریز کرنا۔ [198] [199]', 'انفیکشن کے امکانات کو کم کرنے کے حفاظتی اقدامات میں قطرے پلانے ، گھر پر رہنا ، عوام میں ماسک پہننا ، ہجوم کی جگہوں سے گریز کرنا ، دوسروں سے فاصلہ رکھنا ، انڈور خالی جگہوں کو ختم کرنا ، ممکنہ نمائش کے دورانیے کا انتظام کرنا ، [197] صابن اور پانی سے اکثر ہاتھ دھونے میں شامل ہیں۔ [197]اور کم از کم بیس سیکنڈ کے لئے ، سانس کی اچھی حفظان صحت کی مشق کرنا ، اور آنکھوں ، ناک ، یا منہ کو دھوئے ہوئے ہاتھوں سے چھونے سے گریز کرنا۔ [198] [199]', 'COVID-19 کا علاج اور انتظام دونوں معاون نگہداشت کو یکجا کرتا ہے ، جس میں علامات ، سیال تھراپی ، آکسیجن سپورٹ کو ضرورت کے مطابق ، [265] [266] [267] اور منظور شدہ دوائیوں کی بڑھتی ہوئی فہرست شامل کرنے کا علاج شامل ہے۔انتہائی موثر ویکسینوں نے SARS-COV-2 سے م');
